import{z as o,x as B,o as E,c as s,q as n,j as r,D as e,d as i,s as A,S as l}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"树模型：GBDT","description":"","frontmatter":{"title":"树模型：GBDT","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/gbdt-alpha.md","filePath":"quant/gbdt-alpha.md","lastUpdated":1791413859000}'),p={name:"quant/gbdt-alpha.md"};function d(h,a,m,u,D,g){const t=B("Mermaid");return E(),s("div",null,[a[2]||(a[2]=n('<h1 id="树模型-gbdt" tabindex="-1">树模型：GBDT <a class="header-anchor" href="#树模型-gbdt" aria-label="Permalink to &quot;树模型：GBDT&quot;">​</a></h1><div class="epigraph"><p>截面收益的可预测性可以用一套机器学习工具重新估计；其中树与神经网络在样本外改进线性模型，但经济约束与交易成本会把很大一部分增益收走。</p><footer>—— Gu, Kelly and Xiu, Empirical Asset Pricing via Machine Learning, Review of Financial Studies, 2020</footer></div><p>梯度提升树（GBDT）把弱分类回归树加成一个加法模型，用梯度去拟合残差。Friedman（2001）给出梯度提升的统计框架；Chen 与 Guestrin（2016）的 XGBoost、Ke 等（2017）的 LightGBM 使它成为表格数据的默认强基线。Gu、Kelly 与 Xiu（2020）在美国截面上系统比较 OLS、正则线性、随机森林、GBRT 与神经网络，发现非线性方法提高样本外 \\(R^2\\)，并强调树能捕捉交互。Leippold、Wang 与 Zhou（2022）在 A 股得到类似的机器学习可预测性图像。Israel、Kelly 与 Moskowitz（2020）问机器能否「学会金融」；Arnott、Harvey、Kalesnik 与 Linnainmaa 以及 Avramov、Cheng 与 Metzker（2023）加上经济约束与可交易性后，增益显著下降。本篇把 GBDT 当作<strong>截面表格的非线性估计器</strong>：它与<a href="/quant/cs-rank-features">滞后和 rank</a>、<a href="/quant/label-horizon-overlap">标签重叠</a>绑定，而不是当作自动挖 alpha 的引擎。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>线性模型假设特征对收益的效应是加性、全局斜率。价值在极便宜端更强、动量与波动交互、规模改变斜率，这些是树自然能切的分区。问题是金融截面的信噪比低、特征共线、标签重叠、以及结构变化。GBDT 的训练损失可以压得很低，样本外 \\(R^2\\) 仍只有几个百分点甚至为负——这在 Gu–Kelly–Xiu 的表里是常态，不是事故。过拟合表现为：深度过大把单只股票的特异路径记下来、时间泄漏把重叠标签两边都放进训练、以及用随机 K 折选超参。Harvey–Liu–Zhu 的多重检验在这里变成「试了一百组 <code>max_depth</code> 与 <code>learning_rate</code>」。</p><p>树对单调变换不敏感，但仍对缺失编码、宇宙变化与极端值敏感。若不做截面 rank，分裂会优先切成交额、价格这种厚尾列，模型变成隐性的小盘过滤器。若做了 rank 却在全样本上算分位，仍有前视。GBDT 不免除特征纪律，它放大特征纪律的后果。</p><h3 id="提升、随机森林与单棵树" tabindex="-1">提升、随机森林与单棵树 <a class="header-anchor" href="#提升、随机森林与单棵树" aria-label="Permalink to &quot;提升、随机森林与单棵树&quot;">​</a></h3><p>单棵浅树是分区回归，方差小、偏差大。随机森林平均多棵去相关的树，降低方差，Gu–Kelly–Xiu 中森林已强于 OLS。GBDT 顺序拟合残差，同一深度下更易逼近复杂函数，也更易把噪声残差当信号。学习率（shrinkage）与子采样是 Friedman 以来的正则：每棵树只走一小步，并在列或行上随机。XGBoost 的正则项对叶权重做惩罚，LightGBM 的 leaf-wise 生长在金融这种噪声里可以长出很深的不对称树，必须用 <code>min_data_in_leaf</code> 与早停锁住。没有早停的 GBDT 几乎总会过拟合。</p><p><span class="marginnote">特征重要性（gain、split count）在共线族上不稳定：价值的十个近亲会把增益拆散或集中到随机一列。应报告置换重要性或 SHAP 的分组值，并检查不同年份的稳定性，而不是把某一列的 gain 写成经济学发现。</span></p><p><span class="marginnote">「梯度提升」名字吓人，直白版是：先给一个粗答案，然后反复问「我刚才错在哪」——每棵新树专门学前面所有树留下的错误，把成千上万个小修正加总成强模型。学习率（如 0.05）表示每次只采纳新树意见的百分之五，像小剂量多次服药：稳，但需要更多棵树。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>设计矩阵。</strong> 行为可交易日与股票，列为滞后且截面变换后的特征，标签为未来 \\(h\\) 期收益或残差，见前两篇。训练只使用 \\(\\mathcal{F}_t\\) 可知的行。缺失保持缺失，让实现把缺失当独立路由，或显式加缺失指示——二者选一并固定。</p><p><strong>时间切分。</strong> Walk-forward：例如用过去 \\(L\\) 年训练，随后一年验证做早停，再随后一年测试，滚动。验证与测试之间 purge 重叠标签。超参只在验证上选一次网格（深度、叶最小样本、学习率、树数上限），禁止看测试再回头。这是把 Gu–Kelly–Xiu 的样本外精神落到工程上。</p><p><span class="marginnote">初学者容易照搬机器学习教材的随机 K 折交叉验证：同一周的股票收益高度相关，把同一时期的信息同时放进训练折和验证折，等于开卷考试。金融表格里唯一的合法切法是沿时间走（walk-forward），并把重叠标签 purge 掉——切分错误比超参选择对结论的破坏大得多。</span></p><p><strong>组合层。</strong> 模型输出 \\(\\hat y_{i,t}\\) 后，在 \\(t\\) 做截面 rank 或分位组合，价值加权，控制行业与规模，报告扣费后多空。Avramov–Cheng–Metzker 显示：加上换手惩罚、排除难交易股票后，ML 的优势缩小。应把这一约束放进验证目标，而不是只在测试末尾「顺便」扣一次费用。Bryzgalova、Pelger 与 Zhu 讨论树与资产定价结构的联系：若关心的是定价核而不是交易，评估应包括对因子模型残差的解释，而不是只看多空夏普。</p><h3 id="损失与不平衡" tabindex="-1">损失与不平衡 <a class="header-anchor" href="#损失与不平衡" aria-label="Permalink to &quot;损失与不平衡&quot;">​</a></h3><p>平方损失被极端收益主导，可用 Huber 或对标签做波动标准化。分类（涨跌）在类别不平衡与重叠下会报出虚假准确率，且与 P&amp;L 不对齐；若用分类，阈值必须在训练窗内生成。分位回归（预测下侧）对风控更有意义，但对 alpha 排序未必更好。Gu–Kelly–Xiu 的主结果是收益预测的 \\(R^2\\)，组合评估是另一步；不要用训练 \\(R^2\\) 代替<a href="/quant/ic-ir-timing">信息比率</a>。</p><p><span class="marginnote">早停要用验证段的<strong>截面</strong>损失或 rank IC，不要用逐点 MSE 的绝对水平：市场波动高的年份 MSE 都会变大，早停会误判。IC 或 Spearman 更接近排序交易的目标。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>GBDT 的第 \\(m\\) 棵树拟合损失对当前预测的负梯度。平方损失下就是拟合残差。金融残差含一个巨大的不可预测成分，提升在后期专攻这个成分，样本内 \\(R^2\\) 上升、样本外下降——这就是必须早停的机制。子采样使每棵树看不到全部噪声模式，类似收缩。列采样减少对某一共线特征的依赖，但会让重要性更随机。</p>',20)),(E(),r(l,null,{default:e(()=>[A(t,{id:"mermaid-58",class:"mermaid",graph:"flowchart%20TD%0A%20%20Y%5B%22%E6%A0%87%E7%AD%BE%20y%20%E4%B8%8E%E5%BD%93%E5%89%8D%E9%A2%84%E6%B5%8B%20yhat%22%5D%20--%3E%20Res%5B%22%E8%B4%9F%E6%A2%AF%E5%BA%A6%EF%BC%9A%E5%B9%B3%E6%96%B9%E6%8D%9F%E5%A4%B1%E4%B8%8B%E5%B0%B1%E6%98%AF%E6%AE%8B%E5%B7%AE%22%5D%0A%20%20Res%20--%3E%20Tm%5B%22%E7%AC%AC%20m%20%E6%A3%B5%E6%B5%85%E6%A0%91%E6%8B%9F%E5%90%88%E6%AE%8B%E5%B7%AE%22%5D%0A%20%20Tm%20--%3E%20Up%5B%22%E9%A2%84%E6%B5%8B%E6%9B%B4%E6%96%B0%EF%BC%9Ayhat%20%E5%8A%A0%E4%B8%8A%E5%AD%A6%E4%B9%A0%E7%8E%87%20%C3%97%20%E6%A0%91%E8%BE%93%E5%87%BA%22%5D%0A%20%20Up%20--%3E%20Q%7B%22%E8%BD%AE%E6%AC%A1%E6%97%A9%E6%99%9A%22%7D%0A%20%20Q%20--%3E%7C%22%E6%97%A9%E6%9C%9F%22%7C%20Sig%5B%22%E6%AE%8B%E5%B7%AE%E9%87%8C%E8%BF%98%E6%9C%89%E5%8F%AF%E5%AD%A6%E7%9A%84%E6%A8%AA%E6%88%AA%E9%9D%A2%E4%BF%A1%E5%8F%B7%22%5D%0A%20%20Q%20--%3E%7C%22%E5%90%8E%E6%9C%9F%22%7C%20Nz%5B%22%E6%AE%8B%E5%B7%AE%E8%BF%91%E4%BC%BC%E7%89%B9%E5%BC%82%E5%99%AA%E5%A3%B0%EF%BC%8C%E6%A0%91%E5%9C%A8%E8%83%8C%E7%9B%98%22%5D%0A%20%20Sig%20--%3E%20Loop%5B%22%E7%BB%A7%E7%BB%AD%E8%AE%AD%E7%BB%83%E4%B8%8B%E4%B8%80%E6%A3%B5%22%5D%0A%20%20Nz%20--%3E%20ES%5B%22%E9%AA%8C%E8%AF%81%E6%AE%B5%20IC%20%E4%B8%8D%E5%86%8D%E4%B8%8A%E5%8D%87%EF%BC%9A%E6%97%A9%E5%81%9C%E6%88%AA%E6%96%AD%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=n('<p><span class="marginnote">数字实例：样本外 \\(R^2=0.5\\%\\) 听起来毫无用处，但它的分母是「每只股票每天收益的方差」——绝大部分是不可预测的特异波动。只要模型在排序的前后两端做对，千分之几的预测力就足以支撑多空组合。这就是论文里 \\(R^2\\) 很小与实盘有 IR 并不矛盾的原因。</span></p><p>交互：树用一次分裂序列逼近 \\(x_1\\times x_2\\) 型效应，这是相对线性模型的主要经济借口（例如高波动时动量失效）。检验交互是否真实，应看分样本 IC 是否与分裂给出的分区一致，并在测试年保持，而不是只看 SHAP 交互图的漂亮。Regime 切换时，旧分区失效，必须靠滚动训练更新；全样本训练一张「永恒的树」与金融非平稳不相容，见体制风险类讨论。</p><p>与正则线性的分工：线性模型在低信噪、近线性的特征（beta、规模）上更稳；GBDT 把预算留给真正的弯曲与交互。把两者做成残差学习（先线性，再对残差提升）往往比单用深度树更可审计，也更接近 Friedman 的梯度提升本意——在一个可解释的均值上修非线性。</p><h3 id="中国市场与约束" tabindex="-1">中国市场与约束 <a class="header-anchor" href="#中国市场与约束" aria-label="Permalink to &quot;中国市场与约束&quot;">​</a></h3><p>Leippold–Wang–Zhou（2022）表明 A 股上 ML 可预测性存在，但涨跌停、T+1、散户占比与会计质量改变特征含义。验证目标必须含不可交易日：预测涨停打开前无法买入的标签，应在损失里视为不可实现，否则树会去学「涨停余波」。借券与融券限制使空头腿与美股论文不可比，多空夏普要拆开报告。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要用随机森林/GBDT 的默认参数在全样本拟合一次然后报告夏普。不要把测试期的早停当合法（那是用测试做训练）。不要把新闻、卫星、卡、货运几十列无纪律地堆进同一棵树：共线与体制共动让 importance 变成供应商排行榜，增量 \\(R^2\\) 应逐族加入。计算上，日频全宇宙 million 级行需要按年分块与列抽样，但这是工程，不能成为减少 purge 的理由。</p><p>可解释性：给投资过程的应是分位组合与分样本 IC，而不是 400 棵树的图。监管与风控要的是暴露，GBDT 输出必须再映射回可加的因子与残差，否则<a href="/quant/trading-kill-switch">闸门</a>无法对「模型觉得该空」设限。</p><p><span class="marginnote">Gu–Kelly–Xiu 没有声称 GBDT 击败了成本与拥挤。把他们的样本外 \\(R^2\\) 翻译成实盘杠杆，是把论文里的统计对象当成了 Kelly 公式里的 \\(\\mu\\)。</span></p>',9)),(E(),r(l,null,{default:e(()=>[A(t,{id:"mermaid-86",class:"mermaid",graph:"flowchart%20TD%0A%20%20F%5B%22%E6%BB%9E%E5%90%8E%E4%B8%94%E6%88%AA%E9%9D%A2%20rank%20%E7%9A%84%E7%89%B9%E5%BE%81%22%5D%20--%3E%20WF%5B%22Walk-forward%20%E8%AE%AD%E7%BB%83%22%5D%0A%20%20L%5B%22%E5%AF%B9%E9%BD%90%E5%90%8E%E7%9A%84%E6%A0%87%E7%AD%BE%20y_h%22%5D%20--%3E%20WF%0A%20%20WF%20--%3E%20ES%5B%22%E9%AA%8C%E8%AF%81%E6%AE%B5%E6%97%A9%E5%81%9C%20%2F%20%E9%94%81%E8%B6%85%E5%8F%82%22%5D%0A%20%20ES%20--%3E%20YHAT%5B%22%E6%A0%B7%E6%9C%AC%E5%A4%96%20yhat%22%5D%0A%20%20YHAT%20--%3E%20CS%5B%22%E6%88%AA%E9%9D%A2%E6%8E%92%E5%BA%8F%E4%B8%8E%E4%B8%AD%E6%80%A7%22%5D%0A%20%20CS%20--%3E%20COST%5B%22%E6%8D%A2%E6%89%8B%E4%B8%8E%E5%8F%AF%E4%BA%A4%E6%98%93%E7%BA%A6%E6%9D%9F%22%5D%0A%20%20COST%20--%3E%20OOS%5B%22%E6%B5%8B%E8%AF%95%E6%9C%9F%20IR%20%2F%20%E6%89%A3%E8%B4%B9%E5%A4%8F%E6%99%AE%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[i(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=n('<h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Friedman（2001）的梯度提升与 XGBoost / LightGBM 实现，使 GBDT 成为表格截面的标准非线性基线；正则与早停是必需品，不是可选项。</li><li>Gu–Kelly–Xiu（2020）表明树与网络在样本外改进线性模型；Avramov–Cheng–Metzker（2023）与成本、经济约束表明可交易增益更小。</li><li>时间切分、purge、截面验证指标、按列滞后与 rank，比树的深度更决定是否泄漏。</li><li>重要性不等于经济学；交互必须在测试年的分样本 IC 上复核。A 股须把涨跌停与 T+1 写进损失（Leippold–Wang–Zhou, 2022）。</li><li>出处：Friedman, <em>Annals of Statistics</em>, 2001；Chen and Guestrin, <em>KDD</em>, 2016；Ke et al., <em>NeurIPS</em>, 2017；Gu, Kelly and Xiu, <em>RFS</em>, 2020；Leippold, Wang and Zhou, <em>JFE</em>, 2022；Israel, Kelly and Moskowitz, <em>Journal of Investment Management</em>, 2020；Avramov, Cheng and Metzker, <em>Management Science</em>, 2023。</li></ul>',2))])}const _=o(p,[["render",d]]);export{C as __pageData,_ as default};
